use std::collections::HashMap;
use std::hash::Hash;

pub struct HopscotchMap<K, V> {
    entries: HashMap<K, V>,
    bucket_count: u64,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            entries: HashMap::new(),
            bucket_count: 0,
        }
    }

    pub fn reserve(&mut self, count: i32) {
        let requested = bucket_count_for_requested(count);
        let occupied = if self.entries.is_empty() {
            0
        } else {
            bucket_count_for_size(self.entries.len() as u64)
        };

        self.bucket_count = self.bucket_count.max(requested).max(occupied);

        if count > 0 {
            self.entries.reserve(count as usize);
        }
    }

    pub fn insert(&mut self, entry: (K, V)) -> bool {
        let (key, value) = entry;

        if self.entries.contains_key(&key) {
            return false;
        }

        let next_len = self.entries.len() as u64 + 1;
        if self.bucket_count == 0 || next_len > max_entries_for_buckets(self.bucket_count) {
            self.bucket_count = bucket_count_for_size(next_len);
        }

        self.entries.insert(key, value);
        true
    }

    pub fn size(&self) -> usize {
        self.entries.len()
    }

    pub fn bucket_count(&self) -> u64 {
        self.bucket_count
    }

    pub fn overflow_size(&self) -> usize {
        0
    }
}

impl<K, V> Default for HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    fn default() -> Self {
        Self::new()
    }
}

fn bucket_count_for_requested(count: i32) -> u64 {
    if count <= 0 {
        0
    } else {
        bucket_count_for_size(count as u64)
    }
}

fn bucket_count_for_size(count: u64) -> u64 {
    let mut buckets = 2_u64;

    while max_entries_for_buckets(buckets) < count {
        buckets = buckets.checked_mul(2).expect("bucket count overflow");
    }

    buckets
}

fn max_entries_for_buckets(bucket_count: u64) -> u64 {
    bucket_count.saturating_mul(9) / 10
}

